1	import { addDays, addMonths } from './dates.js';
2	
3	/** Billing cycles a plan can have. */
4	export const CYCLE = Object.freeze({ MONTH: 'monthly', YEAR: 'yearly', WEEK: 'weekly' });
5	
6	/** Every supported cycle, as stored in the subscriptions file. */
7	export const CYCLES = Object.freeze(Object.values(CYCLE));
8	
9	const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12, [CYCLE.WEEK]: 12 / 52 };
10	
11	/**
12	 * What a plan costs per month, in whole cents (rounded to the nearest cent).
13	 * @param {{ price: number, cycle: string }} sub
14	 * @returns {number}
15	 */
16	export function monthlyCents(sub) {
17	  return Math.round(sub.price / MONTHS_PER_CHARGE[sub.cycle]);
18	}
19	
20	/**
21	 * The date of a plan's next charge on or after `today` ('YYYY-MM-DD').
22	 * Monthly/yearly charges fall on the day of the month of the first charge, or the last day of a shorter month.
23	 * Weekly charges fall every 7 days.
24	 * @param {{ cycle: string, since: string }} sub
25	 * @param {string} today
26	 * @returns {string}
27	 */
28	export function nextCharge(sub, today) {
29	  if (sub.cycle === CYCLE.WEEK) {
30	    let n = 0;
31	    let date = sub.since;
32	    while (date < today) {
33	      n += 1;
34	      date = addDays(sub.since, n * 7);
35	    }
36	    return date;
37	  }
38	  const step = MONTHS_PER_CHARGE[sub.cycle];
39	  let n = 0;
40	  let date = sub.since;
41	  while (date < today) {
42	    n += 1;
43	    date = addMonths(sub.since, n * step);
44	  }
45	  return date;
46	}
